 useEffect(()=>{setDebtAction(null);setDebtContext(undefined);setGroup(false);setContractKind(null);setOpening(null);setTransfer(null);setPayable(null);setPersonalPayable(null);setShowAdvances(false);setShowOpening(false);setPersonalFunding(null);setTab(view==='debt-report'?'summary':view==='debts'?initialDebtSide:view==='position'?'summary':'all');},[scope,initialDebtSide,view]);
